const scheme = $('Has Free-Text Criteria?').item.json;
let parsed = null;
try {
  const content = $json.choices && $json.choices[0] && $json.choices[0].message ? $json.choices[0].message.content : null;
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  parsed = null;
}
const meta = { name: scheme.name, source_url: scheme.source_url, last_verified: scheme.last_verified, benefits: scheme.benefits };
if (!parsed || typeof parsed.eligible === 'undefined') {
  return { json: { scheme_id: scheme.id, ...meta, eligible: false, confidence: 'low', matched_criteria: ['income threshold', 'occupation match'], failed_criteria: ['free-text criterion could not be evaluated'], explanation: 'Hard rules passed but the free-text criterion evaluation could not be parsed; needs manual review.' } };
}
const criterion = parsed.criterion || 'free-text criterion';
return { json: { scheme_id: scheme.id, ...meta, eligible: !!parsed.eligible, confidence: 'medium', matched_criteria: parsed.eligible ? ['income threshold', 'occupation match', criterion] : ['income threshold', 'occupation match'], failed_criteria: parsed.eligible ? [] : [criterion], explanation: parsed.reasoning || 'No reasoning provided.' } };

const profile = $json.profile || {};
const income = Number(profile.income || 0);
const maxIncome = Number($json.max_family_income_inr || 0);
const schemeOcc = String($json.occupation || '').toLowerCase().trim();
const profOcc = String(profile.occupation || '').toLowerCase().trim();
const failed = [];
const matched = [];
if (maxIncome && income > maxIncome) {
  failed.push('income threshold (income ' + income + ' exceeds max ' + maxIncome + ')');
} else {
  matched.push('income threshold');
}
if (schemeOcc && schemeOcc !== 'any' && schemeOcc !== profOcc) {
  failed.push('occupation match (requires ' + schemeOcc + ', applicant is ' + (profOcc || 'unknown') + ')');
} else {
  matched.push('occupation match');
}
return { json: { scheme_id: $json.id, name: $json.name, source_url: $json.source_url, last_verified: $json.last_verified, benefits: $json.benefits, eligible: false, confidence: 'high', matched_criteria: matched, failed_criteria: failed, explanation: 'Failed hard rules: ' + failed.join('; ') } };
